-- Ce qui restait en français dans les 4 autres langues (relevé du 18/11 sur
-- le site en ligne, à la demande d'Alexandra : « Thèmes & paysages n'est pas
-- traduit », « faut être sûr d'avoir toutes les langues ») : les 10 rayons,
-- les 4 modes de livraison, le lieu de retrait du marché de Noël, la
-- promotion « 3 achetées = 1 A4 offerte », l'entrée « TOUT VOIR » du menu et
-- les 4 pages légales (précédées d'un avertissement : la version française
-- fait foi). Même règle que la 0094 : rien n'est écrasé, une ligne renommée
-- depuis le relevé est laissée telle quelle.
UPDATE "collection" x
SET "translations" = coalesce(x."translations", '{}'::jsonb) || (
    SELECT jsonb_object_agg(l.key, l.value || coalesce((
      SELECT jsonb_object_agg(e.key, e.value)
      FROM jsonb_each(CASE WHEN jsonb_typeof(x."translations" -> l.key) = 'object' THEN x."translations" -> l.key ELSE '{}'::jsonb END) e
      WHERE (jsonb_typeof(e.value) = 'string' AND btrim(e.value #>> '{}') <> '')
         OR (jsonb_typeof(e.value) = 'array' AND jsonb_array_length(e.value) > 0)
    ), '{}'::jsonb))
    FROM jsonb_each(t.trad) l
  )
FROM (VALUES
  (1, 'accessoires', 'Accessoires', '{"en":{"name":"Accessories","description":"<p><meta charset=\"utf-8\">Fall for our selection of original, on-trend <strong data-start=\"223\" data-end=\"248\">little gift ideas</strong>: <strong data-start=\"273\" data-end=\"301\">personalised keyrings</strong>, <strong data-start=\"303\" data-end=\"324\">decorative frames</strong>, <strong data-start=\"326\" data-end=\"364\">socks with fun messages</strong> and many other unique accessories. Ideal as a gift for a <strong data-start=\"432\" data-end=\"448\">birthday</strong>, <strong data-start=\"453\" data-end=\"461\">Christmas</strong> or <strong data-start=\"469\" data-end=\"487\">Valentine’s Day</strong>, or simply to bring a smile any day of the year, these <strong data-start=\"539\" data-end=\"573\">affordable, original gifts</strong> add a touch of humour, tenderness or style. Perfect for surprising your loved ones, our <strong data-start=\"673\" data-end=\"713\">personalised gifts and decorative objects</strong> fit easily at home, at the office or even on the go. These <strong data-start=\"791\" data-end=\"824\">thoughtful little extras</strong> are a great way to thank a friend, spoil a family member or add a fun, warm touch to your everyday life.</p>"},"de":{"name":"Accessoires","description":"<p><meta charset=\"utf-8\">Entdecken Sie unsere Auswahl an originellen und trendigen <strong data-start=\"223\" data-end=\"248\">kleinen Geschenkideen</strong>: <strong data-start=\"273\" data-end=\"301\">personalisierte Schlüsselanhänger</strong>, <strong data-start=\"303\" data-end=\"324\">dekorative Rahmen</strong>, <strong data-start=\"326\" data-end=\"364\">Socken mit lustigen Sprüchen</strong> und viele weitere einzigartige Accessoires. Ideal als Geschenk zum <strong data-start=\"432\" data-end=\"448\">Geburtstag</strong>, zu <strong data-start=\"453\" data-end=\"461\">Weihnachten</strong>, zum <strong data-start=\"469\" data-end=\"487\">Valentinstag</strong> oder einfach als kleine Freude im Alltag: Diese <strong data-start=\"539\" data-end=\"573\">günstigen und originellen Geschenke</strong> bringen Humor, Zärtlichkeit oder Stil. Perfekt, um Ihre Liebsten zu überraschen: Unsere <strong data-start=\"673\" data-end=\"713\">personalisierten Geschenke und Deko-Objekte</strong> finden ganz leicht ihren Platz zu Hause, im Büro oder sogar auf Reisen. Diese <strong data-start=\"791\" data-end=\"824\">kleinen originellen Aufmerksamkeiten</strong> sind eine wunderbare Idee, um sich bei Freunden zu bedanken, ein Familienmitglied zu verwöhnen oder Ihrem Alltag eine fröhliche, herzliche Note zu verleihen.</p>"},"it":{"name":"Accessori","description":"<p><meta charset=\"utf-8\">Lasciati conquistare dalla nostra selezione di <strong data-start=\"223\" data-end=\"248\">piccoli oggetti regalo</strong> originali e di tendenza: <strong data-start=\"273\" data-end=\"301\">portachiavi personalizzati</strong>, <strong data-start=\"303\" data-end=\"324\">cornici decorative</strong>, <strong data-start=\"326\" data-end=\"364\">calzini con messaggi divertenti</strong> e tanti altri accessori unici. Ideali da regalare per un <strong data-start=\"432\" data-end=\"448\">compleanno</strong>, per <strong data-start=\"453\" data-end=\"461\">Natale</strong>, per <strong data-start=\"469\" data-end=\"487\">San Valentino</strong> o semplicemente per fare un piacere ogni giorno, questi <strong data-start=\"539\" data-end=\"573\">regali economici e originali</strong> portano un tocco di umorismo, tenerezza o stile. Perfetti per sorprendere i tuoi cari, i nostri <strong data-start=\"673\" data-end=\"713\">regali personalizzati e oggetti decorativi</strong> trovano facilmente posto in casa, in ufficio o persino in viaggio. Queste <strong data-start=\"791\" data-end=\"824\">piccole attenzioni originali</strong> sono un’ottima idea per ringraziare un amico, coccolare un familiare o portare una nota allegra e calorosa nella tua quotidianità.</p>"},"es":{"name":"Accesorios","description":"<p><meta charset=\"utf-8\">Déjate conquistar por nuestra selección de <strong data-start=\"223\" data-end=\"248\">pequeños regalos</strong> originales y de tendencia: <strong data-start=\"273\" data-end=\"301\">llaveros personalizados</strong>, <strong data-start=\"303\" data-end=\"324\">marcos decorativos</strong>, <strong data-start=\"326\" data-end=\"364\">calcetines con mensajes divertidos</strong> y muchos otros accesorios únicos. Ideales para regalar en un <strong data-start=\"432\" data-end=\"448\">cumpleaños</strong>, en <strong data-start=\"453\" data-end=\"461\">Navidad</strong>, en <strong data-start=\"469\" data-end=\"487\">San Valentín</strong> o simplemente para dar una alegría cualquier día, estos <strong data-start=\"539\" data-end=\"573\">regalos baratos y originales</strong> aportan un toque de humor, ternura o estilo. Perfectos para sorprender a tus seres queridos, nuestros <strong data-start=\"673\" data-end=\"713\">regalos personalizados y objetos decorativos</strong> encuentran fácilmente su lugar en casa, en la oficina o incluso de viaje. Estos <strong data-start=\"791\" data-end=\"824\">pequeños detalles originales</strong> son una excelente idea para dar las gracias a un amigo, mimar a un familiar o aportar una nota divertida y cálida a tu día a día.</p>"}}'::jsonb),
  (5, 'affiches-diverses', 'Affiches prêtes à imprimer', '{"en":{"name":"Ready-to-print posters","description":"<h5>\n<meta charset=\"utf-8\">Bring a touch of style and character to your spaces with our collection of <strong data-start=\"248\" data-end=\"272\">decorative posters</strong>. Printed in high quality, these <strong data-start=\"306\" data-end=\"324\">design posters</strong> fit perfectly into any interior: living room, bedroom, kitchen, as well as <strong data-start=\"422\" data-end=\"448\">professional offices</strong>, shops, restaurants and boutiques. Inspired by the latest <strong data-start=\"517\" data-end=\"542\">wall decor trends</strong>, our <strong data-start=\"548\" data-end=\"569\">modern posters</strong> enhance your walls and create a unique atmosphere, whether minimalist, vintage, artistic or contemporary. Easy to frame and available in several sizes, they are an ideal way to quickly transform a room, dress up a workspace or give a shop extra character. Make your interior decor a true reflection of your style with our <strong data-start=\"967\" data-end=\"1007\">ready-to-hang decorative posters</strong>.</h5>"},"de":{"name":"Druckfertige Poster","description":"<h5>\n<meta charset=\"utf-8\">Verleihen Sie Ihren Räumen Stil und Charakter mit unserer Kollektion <strong data-start=\"248\" data-end=\"272\">dekorativer Poster</strong>. In hoher Qualität gedruckt, passen diese <strong data-start=\"306\" data-end=\"324\">Designposter</strong> in jede Einrichtung: Wohnzimmer, Schlafzimmer, Küche, aber auch <strong data-start=\"422\" data-end=\"448\">Büros</strong>, Geschäfte, Restaurants und Boutiquen. Inspiriert von den aktuellen <strong data-start=\"517\" data-end=\"542\">Trends der Wanddekoration</strong> verschönern unsere <strong data-start=\"548\" data-end=\"569\">modernen Poster</strong> Ihre Wände und schaffen eine einzigartige Atmosphäre – ob minimalistisch, vintage, künstlerisch oder zeitgenössisch. Leicht zu rahmen und in verschiedenen Formaten erhältlich, sind sie die ideale Lösung, um einen Raum im Handumdrehen zu verwandeln, einen Arbeitsplatz zu gestalten oder einem Geschäft eine besondere Note zu verleihen. Machen Sie Ihre Einrichtung zu einem echten Spiegel Ihres Stils – mit unseren <strong data-start=\"967\" data-end=\"1007\">dekorativen Postern, fertig zum Aufhängen</strong>.</h5>"},"it":{"name":"Poster pronti da stampare","description":"<h5>\n<meta charset=\"utf-8\">Dai un tocco di stile e carattere ai tuoi spazi con la nostra collezione di <strong data-start=\"248\" data-end=\"272\">poster decorativi</strong>. Stampati in alta qualità, questi <strong data-start=\"306\" data-end=\"324\">poster di design</strong> si integrano perfettamente in ogni ambiente: soggiorno, camera da letto, cucina, ma anche <strong data-start=\"422\" data-end=\"448\">uffici professionali</strong>, negozi, ristoranti e boutique. Ispirati alle <strong data-start=\"517\" data-end=\"542\">tendenze della decorazione murale</strong>, i nostri <strong data-start=\"548\" data-end=\"569\">poster moderni</strong> valorizzano le tue pareti e creano un’atmosfera unica, minimalista, vintage, artistica o contemporanea. Facili da incorniciare e disponibili in diversi formati, sono la soluzione ideale per trasformare rapidamente una stanza, arredare uno spazio di lavoro o dare carattere a un negozio. Fai del tuo arredamento il vero riflesso del tuo stile con i nostri <strong data-start=\"967\" data-end=\"1007\">poster decorativi pronti da appendere</strong>.</h5>"},"es":{"name":"Láminas listas para imprimir","description":"<h5>\n<meta charset=\"utf-8\">Aporta un toque de estilo y carácter a tus espacios con nuestra colección de <strong data-start=\"248\" data-end=\"272\">láminas decorativas</strong>. Impresas en alta calidad, estas <strong data-start=\"306\" data-end=\"324\">láminas de diseño</strong> encajan perfectamente en cualquier interior: salón, dormitorio, cocina, pero también en <strong data-start=\"422\" data-end=\"448\">oficinas profesionales</strong>, comercios, restaurantes o tiendas. Inspiradas en las <strong data-start=\"517\" data-end=\"542\">tendencias de decoración mural</strong>, nuestras <strong data-start=\"548\" data-end=\"569\">láminas modernas</strong> embellecen tus paredes y crean un ambiente único, ya sea minimalista, vintage, artístico o contemporáneo. Fáciles de enmarcar y disponibles en varios formatos, son la solución ideal para transformar rápidamente una habitación, decorar un espacio de trabajo o dar personalidad a una tienda. Haz de tu decoración un verdadero reflejo de tu estilo con nuestras <strong data-start=\"967\" data-end=\"1007\">láminas decorativas listas para colgar</strong>.</h5>"}}'::jsonb),
  (6, 'collection-tout-voir', 'Collection TOUT VOIR', '{"en":{"name":"SEE ALL collection"},"de":{"name":"Kollektion ALLE ANSEHEN"},"it":{"name":"Collezione VEDI TUTTI"},"es":{"name":"Colección VER TODO"}}'::jsonb),
  (7, 'cuisine', 'Cuisine', '{"en":{"name":"Kitchen"},"de":{"name":"Küche"},"it":{"name":"Cucina"},"es":{"name":"Cocina"}}'::jsonb),
  (11, 'frontpage', 'Page d''accueil / En vedette', '{"en":{"name":"Home page / Featured"},"de":{"name":"Startseite / Empfohlen"},"it":{"name":"Home page / In evidenza"},"es":{"name":"Inicio / Destacados"}}'::jsonb),
  (13, 'personnages-de-face', 'Personnages de FACE', '{"en":{"name":"Characters from the FRONT"},"de":{"name":"Figuren von VORNE"},"it":{"name":"Personaggi di FRONTE"},"es":{"name":"Personajes de FRENTE"}}'::jsonb),
  (12, 'personnages-de-dos', 'Personnages de dos', '{"en":{"name":"Characters from behind"},"de":{"name":"Figuren von hinten"},"it":{"name":"Personaggi di spalle"},"es":{"name":"Personajes de espaldas"}}'::jsonb),
  (16, 'balades-paysages', 'Thèmes & paysages', '{"en":{"name":"Themes and landscapes"},"de":{"name":"Themen und Landschaften"},"it":{"name":"Temi e paesaggi"},"es":{"name":"Temas y paisajes"}}'::jsonb),
  (17, 'villes', 'Villes', '{"en":{"name":"Towns and cities"},"de":{"name":"Städte"},"it":{"name":"Città"},"es":{"name":"Ciudades"}}'::jsonb),
  (19, 'a-partir-de-photos', 'À partir de photos', '{"en":{"name":"From your photos"},"de":{"name":"Aus Ihren Fotos"},"it":{"name":"Dalle tue foto"},"es":{"name":"A partir de tus fotos"}}'::jsonb)
