  ('mondial_relay', 'Point relais', '{"en":{"name":"Relay point","description":"Mondial Relay — 3 to 5 working days"},"de":{"name":"Paketshop","description":"Mondial Relay — 3 bis 5 Werktage"},"it":{"name":"Punto relais","description":"Mondial Relay — da 3 a 5 giorni lavorativi"},"es":{"name":"Punto de recogida","description":"Mondial Relay — de 3 a 5 días laborables"}}'::jsonb),
