  ('colissimo_relais', 'Point de retrait', '{"en":{"name":"Collection point","description":"Colissimo — post office, shop or parcel locker"},"de":{"name":"Abholstelle","description":"Colissimo — Postfiliale, Geschäft oder Paketstation"},"it":{"name":"Punto di ritiro","description":"Colissimo — ufficio postale, negozio o locker"},"es":{"name":"Punto de entrega","description":"Colissimo — oficina de correos, comercio o taquilla"}}'::jsonb),
  ('retrait-au-stand', 'Retrait au stand', '{"en":{"name":"Collect at our stand","description":"Free: collect your poster at our stand."},"de":{"name":"Abholung an unserem Stand","description":"Kostenlos: Holen Sie Ihr Poster an unserem Stand ab."},"it":{"name":"Ritiro al nostro stand","description":"Gratis: vieni a ritirare il tuo poster al nostro stand."},"es":{"name":"Recogida en nuestro puesto","description":"Gratis: ven a recoger tu lámina a nuestro puesto."}}'::jsonb)
